/* ============================================================
 * data.js — конфиг ивента и контент историй.
 *
 * Формат сцены:
 *   { bg, who, emo, heroEmo, text }        — реплика (who: null = рассказчик)
 *   { label: 'x' }                         — метка для переходов
 *   { if: {...} }                          — сцена показывается только при условии
 *   { goto: 'x' }                          — переход (можно с if)
 *   { cutscene: 'csId' }                   — открытие кат-сцены
 *   { choice: { id, prompt, options } }    — точка выбора
 * Опция выбора:
 *   { text, cost?, rel?: {charId: ±n}, flag?: {k: v}, goto?, cutscene? }
 *   cost — цена в валюте выборов (сердца); платный выбор.
 * Условия if:
 *   { flag: 'k', eq: v } | { rel: 'charId', gte: n } | { outfit: 'advent' }
 * ============================================================ */

